select date_format(c.signup_date, 'yyyy-MM') as signup_month, case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, max(a.balance) - min(a.balance) as balance_range, sum(case when a.account_type = 'SAVINGS' then a.balance else 0 end) as savings_balance from accounts a inner join customers c on a.customer_id = c.id group by date_format(c.signup_date, 'yyyy-MM'), case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end
